-- Chinese Classic series re-run merchandise (Origins, Spiritforged, Unleashed designs). Safe to run more than once.
insert into promo_items (id, r, data)
select 'item-10813', 10813, $j${"cat": "COLLECTIBLE", "nm": "Classic Series Deck Box - Origins (Navy)", "se": "N/A", "cn": "N/A", "ra": "N/A", "do": "N/A", "tg": "Deck Box\nClassic Series\nOrigins", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/classic-series-deck-box-origins-navy-ch-item-10813.webp", "inf": "Deck Box from the Chinese Classic series merchandise re-run, Origins design (navy). Sold at the Season 4 Regional Open Summoner Shop, limited to 1 per product per purchase.", "r": 10813, "id": "item-10813", "la": "Chinese", "ev": "China - Classic series merchandise", "ty": "Deck Box", "fo": false, "tn": false, "me": false, "nn": false, "bm": false, "pw": false, "pt": ""}$j$::jsonb || jsonb_build_object('st', coalesce((select data->>'st' from promo_items where upper(data->>'st')='NEED' limit 1),'NEED'))
where not exists (select 1 from promo_items where id = 'item-10813' or (data->>'nm' = $n$Classic Series Deck Box - Origins (Navy)$n$ and data->>'la' = 'Chinese'));
